import { Link } from 'gatsby';

const classes = {
  heading:
    'pt-12 font-semibold tracking-widest text-sm text-gray-200 leading-normal uppercase',
  card: 'block mt-6 bg-gray-900/70 border border-white/10 rounded-lg p-6 shadow-lg transition-all duration-150 hover:border-retroGold/50 hover:-translate-y-0.5 md:p-8',
  title: 'text-2xl text-gray-100 font-bold group-hover:text-retroGold',
  date: 'mt-1 text-sm text-gray-400 font-light',
  description: 'mt-3 text-gray-300 font-light',
  readMore: 'mt-4 inline-block text-sm font-semibold text-retroGold',
};

const BlogPosts = ({ posts }) => {
  return (
    <div>
      <h2 className={classes.heading}>All Blog Posts</h2>
      {posts.map((post) => (
        <Link
          key={post.node.fields.slug}
          className={`group ${classes.card}`}
          to={post.node.fields.slug}
        >
          <h3 className={classes.title}>{post.node.frontmatter.title}</h3>
          <p className={classes.date}>{post.node.frontmatter.date}</p>
          <p className={classes.description}>
            {post.node.frontmatter.description || post.node.excerpt}
          </p>
          <span className={classes.readMore}>Read post &rarr;</span>
        </Link>
      ))}
    </div>
  );
};

export default BlogPosts;
